    $('bw-drawing-standard-profile').value = style.profile.id;
    const customSelect = $('bw-drawing-line-font');
    const selectedCustomId = customSelect.value;
    customSelect.replaceChildren(new Option('New custom line font', ''));
    for (const font of graph.lineFonts) customSelect.append(new Option(font.name, font.id));
    customSelect.value = graph.lineFonts.some((font) => font.id === selectedCustomId) ? selectedCustomId : '';
    const selectedCustom = graph.lineFonts.find((font) => font.id === customSelect.value);
    $('bw-drawing-line-font-update').disabled = !selectedCustom;
    $('bw-drawing-line-font-delete').disabled = !selectedCustom;
