    $('bw-drawing-layer').value = layer.id;
    $('bw-drawing-layer-visible').checked = layer.visible;
    $('bw-drawing-layer-printable').checked = layer.printable;
    const fontSelect = $('bw-drawing-layer-line-font');
    fontSelect.replaceChildren();
    const profileDefaults = drawingStandardTools.defaultStudioDrawingStyle(style.profile.id).layers;
    for (const entry of profileDefaults) fontSelect.append(new Option(entry.lineFont.name, entry.lineFont.id));
    for (const font of graph.lineFonts) fontSelect.append(new Option(font.name + ' (custom)', font.id));
    if (![...fontSelect.options].some((option) => option.value === layer.lineFont.id)) {
      fontSelect.append(new Option(layer.lineFont.name, layer.lineFont.id));
    }
