    $('bw-drawing-sheet-template').value = sheet.format.kind === 'template' ? sheet.format.templateId : 'custom';
    $('bw-drawing-sheet-width').value = String(sheet.format.widthMm);
    $('bw-drawing-sheet-height').value = String(sheet.format.heightMm);
    $('bw-drawing-sheet-width').disabled = sheet.format.kind === 'template';
    $('bw-drawing-sheet-height').disabled = sheet.format.kind === 'template';
