    const target = Math.max(0, Math.min(book.sheets.length - 1, index + delta));
    if (target === index) return;
    const orderedSheetIds = book.sheets.map((entry) => entry.id);
    [orderedSheetIds[index], orderedSheetIds[target]] = [orderedSheetIds[target], orderedSheetIds[index]];
