            const key = color + '|' + radius;
            if (!points.has(key)) points.set(key, { color, radius, path: new Path2D() });
            const [px, py] = toPx(...at(entity.id));
            const path = points.get(key).path;
            path.moveTo(px + radius, py);
            path.arc(px, py, radius, 0, Math.PI * 2);
