          concentric: 4,
          distance: 1,
          angle: 1,
          parallel: 2,
          perpendicular: 1,
          tangent: 1,
          revolute: 5,
          slider: 5,
          width: 3,
          symmetry: 5,
          path: 2,
          'linear-coupler': 1,
          'limit-distance': 0,
          'limit-angle': 0,
